// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 depositAmount) public {
        vm.assume(recipient != address(0) && recipient != address(this));
        depositAmount = bound(depositAmount, 1, 100 ether);
        // Fund the contract
        vm.deal(address(c), depositAmount);
        uint256 recipientBalanceBefore = recipient.balance;
        // Call withdrawAll as owner (this contract)
        c.withdrawAll(recipient);
        uint256 recipientBalanceAfter = recipient.balance;
        // General rule: the recipient's balance increases by exactly the contract balance before the call
        assertTrue(recipientBalanceAfter - recipientBalanceBefore == depositAmount);
    }
}

